def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    size = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}

    transitions = [[-1] * size]
    terminal = [False]

    for pattern in banned:
        state = 0
        for ch in pattern:
            c = char_index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * size)
                terminal.append(False)
            state = transitions[state][c]
        terminal[state] = True

    failure = [0] * len(transitions)
    queue = deque()

    for c in range(size):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]

        for c in range(size):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    safe_states = [state for state in range(len(transitions)) if not terminal[state]]
    index = {state: i for i, state in enumerate(safe_states)}
    count = len(safe_states)

    matrix = [[0] * count for _ in range(count)]
    for state in safe_states:
        row = matrix[index[state]]
        for target in transitions[state]:
            if not terminal[target]:
                row[index[target]] += 1

    vector = [0] * count
    vector[index[0]] = 1

    def multiply_vector(vec, mat):
        result = [0] * count
        for i, value in enumerate(vec):
            if value:
                for j, entry in enumerate(mat[i]):
                    if entry:
                        result[j] = (result[j] + value * entry) % mod
        return result

    def square_matrix(mat):
        result = [[0] * count for _ in range(count)]
        for i in range(count):
            for k, value in enumerate(mat[i]):
                if value:
                    for j, entry in enumerate(mat[k]):
                        if entry:
                            result[i][j] = (result[i][j] + value * entry) % mod
        return result

    while n:
        if n & 1:
            vector = multiply_vector(vector, matrix)
        n >>= 1
        if n:
            matrix = square_matrix(matrix)

    return sum(vector) % mod
